var declarationCount = 1","title":"Coding conventions","source":"https://kotlinlang.org/docs/coding-conventions.html","sections":["Coding conventions > Naming rules > Function names"],"line_start":117,"line_end":122,"score":0.4635162949562073,"release_version":null,"availability":"unknown"},{"anchor":"use-long-in-exported-declarations","start":9908,"end":10498,"split_code":false,"platforms":["js"],"id":"2acd20adaf8e5b999755359c377e388646b2d7453c4c2be926528825ccd52fc3","document_id":"js-to-kotlin-interop","strategy":"semantic","text":"Use Long in exported declarations

